import sys
import math

def main():
    import sys
    import math

    def readints():
        return list(map(int, sys.stdin.readline().split()))

    n = int(sys.stdin.readline())
    heights = readints()

    # Calculate the number of local maxima
    local_maxima = [True] * n
    for i in range(1, n):
        if heights[i] <= heights[i - 1]:
            local_maxima[i] = False
    for i in range(n - 2, -1, -1):
        if heights[i] <= heights[i + 1]:
            local_maxima[i] = False

    # Count the number of local maxima
    max_count = sum(local_maxima)

    # If there are fewer local maxima than n/2, we need to adjust some hills
    result = []
    for k in range(1, math.ceil(n / 2) + 1):
        if k > max_count:
            # We need to adjust some hills to create more local maxima
            # The minimum adjustment needed is the difference between k and max_count
            result.append(k - max_count)
        else:
            # We already have enough local maxima
            result.append(0)

    print(" ".join(map(str, result)))

if __name__ == "__main__":
    main()
